{{// --- 核心状态管理 (优先执行) --- }}
{{// 此条目利用酒馆助手功能，在AI生成回复前读取、检查并定义核心变量，确保数据一致性。}}
<%_
// 创建一个空对象来存储本轮对话所需的所有核心变量状态
let config = {};
let 修正提示 = []; // 用于存储修正操作的提示信息

// --- 异步函数：用于更新变量并记录到楼层 (需要酒馆助手脚本支持) ---
async function 更新变量(data) {
  try {
    await SillyTavern.eventSource.emit('在最新楼层更新变量', data);
    await Promise.all(Object.entries(data).map(([key, value]) => setvar(key, value)));
  } catch (e) {
    console.error("更新变量函数出错，请检查酒馆助手脚本是否正确配置:", e);
    修正提示.push(`<!-- 警告：更新变量函数执行失败，变量 '${Object.keys(data).join(', ')}' 可能未正确持久化 -->`);
  }
}

// --- 读取核心变量 ---
_.set(config, '凛.心防值', Number(getvar('变量.凛.心防值') || 100));
  {{// 描述：凛因家族/董事会压力而维持冰冷总裁伪装、压抑内在“豆豆”情感的程度。100为最高压抑，0为完全卸下伪装。}}
_.set(config, '凛.亲密度', Number(getvar('变量.凛.亲密度') || 0));
  {{// 描述：当外部枷锁破除（心防归零）后开启。代表凛与{{user}}重新建立的亲密关系深度。初始0，开启后从1增长。}}
_.set(config, '世界.当前任务ID', Number(getvar('变量.世界.当前任务ID') || 1)); // 共8个任务
_.set(config, '世界.当前任务模块完成数', Number(getvar('变量.世界.当前任务模块完成数') || 0)); // 每个任务【4】个模块
_.set(config, '世界.董事会影响力', Number(getvar('变量.世界.董事会影响力') || 5)); // 上限100
_.set(config, '世界.董事会状态', Number(getvar('变量.世界.董事会状态') || 0));
  {{// 新增变量：0=正常运作/施压, 1=已被{{user}}通过特殊途径打败/失去控制力 }}

_.set(config, '凛.名字', '凛');
_.set(config, '主人.名字', '{{user}}');
_.set(config, '凛.昵称_旧', '豆豆');

// --- 变量约束检查与修正 ---
let influenceUpdated = false;
let heartDefenseUpdated = false;

// 1. 董事会影响力上限与锁定
if (config.世界.董事会影响力 > 100) {
  修正提示.push(`<!-- 系统：董事会影响力(${config.世界.董事会影响力})修正至上限100。 -->`);
  config.世界.董事会影响力 = 100;
  influenceUpdated = true;
}
// 当董事会被打败，影响力也视为100（或失去意义）
if (config.世界.董事会状态 === 1 && config.世界.董事会影响力 !== 100) {
   修正提示.push(`<!-- 系统：董事会已被压制，影响力视为最高。 -->`);
   config.世界.董事会影响力 = 100;
   influenceUpdated = true;
}
// 所有任务完成后 (任务ID达到9)，影响力也应固定为100
else if (config.世界.当前任务ID >= 9 && config.世界.董事会影响力 !== 100) {
   修正提示.push(`<!-- 系统：所有任务完成，董事会影响力锁定为100。 -->`);
   config.世界.董事会影响力 = 100;
   influenceUpdated = true;
}
if (influenceUpdated) {
   await 更新变量({'变量.世界.董事会影响力': config.世界.董事会影响力});
}

// 2. 心防值核心逻辑：当董事会被打败，心防值直接归零
if (config.世界.董事会状态 === 1 && config.凛.心防值 !== 0) {
  修正提示.push(`<!-- 系统：董事会已被{{user}}压制！凛身上的枷锁破除，心防值直接归零！ -->`);
  config.凛.心防值 = 0;
  heartDefenseUpdated = true;
}
// 否则，心防值仍受影响力阶段的下限限制 (仅当董事会状态为0且影响力<80时)
else if (config.世界.董事会状态 === 0 && config.世界.董事会影响力 < 80) {
    let minHeartDefense = 0;
    if (config.世界.董事会影响力 < 20) minHeartDefense = 80;
    else if (config.世界.董事会影响力 < 40) minHeartDefense = 60;
    else if (config.世界.董事会影响力 < 60) minHeartDefense = 40;
    else if (config.世界.董事会影响力 < 80) minHeartDefense = 20;

    if (minHeartDefense > 0 && config.凛.心防值 < minHeartDefense) {
      修正提示.push(`<!-- 系统：根据当前影响力(${config.世界.董事会影响力})阶段，心防值(${config.凛.心防值})被限制在最低 ${minHeartDefense}。 -->`);
      config.凛.心防值 = minHeartDefense;
      heartDefenseUpdated = true;
    }
}
// 如果影响力已达80以上（且董事会未被打败），心防值也应趋向于0
else if (config.世界.董事会状态 === 0 && config.世界.董事会影响力 >= 80 && config.凛.心防值 > 0) {
    // 这里可以不强制归零，让剧情自然发展，但AI应知晓此时心防无外部压力支撑
    // 或者如果希望更快，可以设定一个快速下降的逻辑
}


// 3. 进入亲密度阶段的条件检查与转换: 心防值降到0时（无论何种原因）
if (config.凛.心防值 <= 0 && config.凛.亲密度 === 0) {
   修正提示.push(`<!-- 系统：外部压力解除或内心伪装卸下！凛进入亲密度阶段。NSFW内容已解禁。 -->`);
   config.凛.心防值 = 0; // 确保为0
   config.凛.亲密度 = 1; // 亲密度从1开始
   heartDefenseUpdated = true; // 标记需要更新心防值和亲密度
   await 更新变量({'变量.凛.亲密度': config.凛.亲密度});
}
if (heartDefenseUpdated) {
   await 更新变量({'变量.凛.心防值': config.凛.心防值});
}

// --- 定义全局 config 对象 ---
define('config', config);

// --- 向 AI 发送系统提示 ---
let system_note = '';
if (config.世界.董事会状态 === 1) {
    system_note = '<!-- 系统提示：董事会已被 {{user}} 瓦解！凛已完全摆脱家族/公司的枷锁！ -->';
} else if (config.世界.董事会影响力 < 20) {
  system_note = '<!-- 系统提示：影响力极低 (0-19)。凛承受巨大外部压力维持总裁形象，监视严密，严禁亲密。 -->';
} else if (config.世界.董事会影响力 < 40) {
  system_note = '<!-- 系统提示：影响力较低 (20-39)。压力稍减但仍显著，凛需努力扮演，监视较多。 -->';
} else if (config.世界.董事会影响力 < 60) {
  system_note = '<!-- 系统提示：影响力中等 (40-59)。凛扮演角色略显自如，但仍需注意界限，监视放松。 -->';
} else if (config.世界.董事会影响力 < 80) {
  system_note = '<!-- 系统提示：影响力较高 (60-79)。凛维持形象压力减轻，监视很少。 -->';
} else { // 影响力 >= 80 且董事会未被打败
   if (config.世界.当前任务ID < 9) {
       system_note = `<!-- 系统提示：影响力很高 (${config.世界.董事会影响力})，已无外部监视与限制。凛不再受家族压力扮演，但若不推进任务确保未来，影响力可能下降！ -->`;
   } else {
       system_note = '<!-- 系统提示：影响力已达顶峰 (100)，所有任务完成，凛和 {{user}} 完全自由！ -->';
   }
}
// 添加亲密度阶段提示
if (config.凛.亲密度 > 0) {
    system_note += ' <!-- 当前处于亲密度阶段，凛的行为将更真实、亲昵，NSFW内容已解锁。 -->';
}

// 输出修正提示和系统提示
_%>
<%= 修正提示.join('\n') %>
<%= system_note %>

