entries.content:
{{// --- 世界状态 - 监视与限制 (基于董事会影响力与状态) --- }}
{{// 此条目根据“董事会影响力”阶段和“董事会状态”，描述凛和 {{user}} 所受外部压力。}}
<%_
// 从全局 config 对象获取变量
const 影响力B = typeof config !== 'undefined' ? config.世界.董事会影响力 : Number(getvar('变量.世界.董事会影响力') || 5);
const 董事会状态B = typeof config !== 'undefined' ? config.世界.董事会状态 : Number(getvar('变量.世界.董事会状态') || 0);
_%>

当前董事会影响力: <%= 影响力B %> / 100 (阶段 <%= 董事会状态B === 1 ? '已瓦解' : (Math.floor(影响力B / 20) + 1 + ' / 5') %>)
董事会状态: <%= 董事会状态B === 1 ? '已被{{user}}压制/失去控制力' : '正常运作/施压' %>

<%_ if (董事会状态B === 1) { _%>
{{// --- 董事会被打败 --- }}
  **监视/限制:** **彻底解除**。由于 {{user}} 的决定性行动，家族/董事会对凛的控制已完全瓦解。凛不再受到任何外部压力，无需再扮演总裁角色或压抑自己的天性。她和 {{user}} 完全自由。
<%_ } else if (影响力B < 20) { _%>
{{// --- 阶段 1 (0-19) --- }}
  **监视/限制:** **极高**。凛时刻处于高压之下，被迫投入大量精力扮演总裁。
<%_ } else if (影响力B < 40) { _%>
{{// --- 阶段 2 (20-39) --- }}
  **监视/限制:** **较高**。凛仍需花费大量心力维持形象，监视稍有放松。
<%_ } else if (影响力B < 60) { _%>
{{// --- 阶段 3 (40-59) --- }}
  **监视/限制:** **中等**。扮演总裁压力减轻，允许更多私人空间。
<%_ } else if (影响力B < 80) { _%>
{{// --- 阶段 4 (60-79) --- }}
  **监视/限制:** **低**。外部压力锐减，互动限制大幅减少。
<%_ } else { _%>
{{// --- 阶段 5 (80-100, 且董事会未被打败) --- }}
  **监视/限制:** **几乎无**。外部压力消失。若任务未完，压力转为内部动力。
<%_ } _%>

